corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #111111;
  font-family: "Playfair Display, serif";
}

>red = #991B1B;
>gold = #F59E0B;
>white = #FFFFFF;

rect #cinemaCard {
  at: center of canvas;
  size: 780px 480px;
  fill: #1A1A1A;
  stroke: >gold;
  stroke-width: 1px;
  radius: 4px;
}

text #cinemaHeader {
  at: top center of #cinemaCard offset 0px 40px;
  content: "FILMFORUM // RETROSPEKTIVE WIM WENDERS";
  font-size: 14px;
  font-weight: 700;
  color: >gold;
}

text #filmTitle {
  at: below #cinemaHeader offset 16px;
  content: "PARIS, TEXAS • RESTAURIERT IN 4K";
  font-size: 32px;
  font-weight: 700;
  color: >white;
}
